                    BaselineCases.RunResult b = BaselineCases.run(c, workRoot.resolve(c.name() + "-" + loc + "-b"));

                    if (!a.allEquals(b)) {
                        failures.add(tag + " determinism self-check failed");
                        System.out.println("[FAIL] " + tag + " determinism self-check");
